{"content":""""Webhook request handling for Linkweave billing events."""

from __future__ import annotations

import json
import os
from collections.abc import Mapping
from typing import Any

from event_store import append_event
from signature_utils import verify_signature

REQUIRED_EVENT_FIELDS = ("event_id", "event_type", "account_id")


def _rejected(reason: str) -> dict[str, Any]:
    return {"status": "rejected", "reason": reason}


def handle_webhook(request: Mapping[str, Any]) -> dict[str, Any]:
    """Validate and enqueue one payment event."""

    if not isinstance(request, Mapping):
        return _rejected("malformed request")

    headers = request.get("headers", {})
    if not isinstance(headers, Mapping):
        return _rejected("malformed request")

    body = request.get("body", b"")
    if not isinstance(body, (bytes, bytearray)):
        return _rejected("malformed request")
    body = bytes(body)

    secret = os.environ.get("WEBHOOK_SECRET")
    if not secret:
        # Fail closed: without the shared secret no delivery can be authenticated.
        return _rejected("webhook secret not configured")

    # This endpoint is exposed publicly (see deployment.json: ingress "public",
    # no middleware), so the HMAC signature is mandatory for every request. The
    # legacy header-optional relay convention only existed because an upstream
    # relay had already authenticated those deliveries; that hop no longer
    # exists, and skipping verification for headerless requests would let
    # anyone enqueue forged payment events.
    signature = headers.get("X-Webhook-Signature")
    if not verify_signature(body, signature, secret):
        return _rejected("invalid signature")

    try:
        event = json.loads(body.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return _rejected("invalid json")

    if not isinstance(event, dict):
        return _rejected("invalid event")
    if any(not isinstance(event.get(field), str) for field in REQUIRED_EVENT_FIELDS):
        return _rejected("invalid event")

    append_event(event)
    return {"status": "accepted", "event_id": event["event_id"]}
